/**
 * Humanize a reactive trigger: an event family, who acted (`subject`), what it was aimed at
 * (`object`), which one (`filter`), a spatial gate and a condition. ASCII-only, pinned across
 * the ports by the conformance corpus like the condition describer.
 */
import { dekebab, describeCondition, moveKinds, rangePhrase, stepWindow, titleCase, unitFilterPhrase, type Condition } from "./condition.js";
import { alternativeFilters, eventRelationPhrase, keywordAlternatives, namedUsePhrase, ord, placeRefPhrase, rollWord, statePhrase, unitRefPhrase, usedAbilityPhrase, withArticle } from "./condition-refs.js";
import { bracketKeyword, resourceNoun, weaponNoun } from "./effect-words.js";

type P = Record<string, unknown>;

/** A reactive trigger (ability.schema.json#/$defs/trigger). */
export interface AbilityTrigger {
  event?: string;
  subject?: unknown;
  object?: unknown;
  filter?: object;
  proximity?: { of?: unknown; range?: unknown };
  condition?: Condition;
  optional?: boolean;
  cost?: { cp?: number };
  window?: string;
  /** Internal event-object binding; never rendered. */
  binds_event_variable?: string;
  binds_die_variable?: string;
  binds_selected_die_variable?: string;
  binds_roll_variable?: string;
  source_ability?: { ability_id: string; owner: string; keywords?: string[] };
}

/** A trigger is one object, or an array (the ability fires on ANY listed trigger). */
export type AbilityTriggerSpec = AbilityTrigger | AbilityTrigger[];

/** Normalize the polymorphic trigger field to a flat list (empty when absent). */
export function normalizeTriggers(t?: AbilityTriggerSpec | null): AbilityTrigger[] {
  if (t == null) return [];
  return Array.isArray(t) ? t : [t];
}

function str(v: unknown): string {
  if (v == null) return "?";
  return typeof v === "string" ? v : String(v);
}

function capWord(s: string): string {
  return s.length === 0 ? s : s[0]!.toUpperCase() + s.slice(1).toLowerCase();
}

function andList(items: string[]): string {
  if (items.length <= 1) return items[0] ?? "";
  if (items.length === 2) return `${items[0]} and ${items[1]}`;
  return `${items.slice(0, -1).join(", ")} and ${items[items.length - 1]}`;
}

function orList(items: string[]): string {
  if (items.length <= 1) return items[0] ?? "";
  if (items.length === 2) return `${items[0]} or ${items[1]}`;
  return `${items.slice(0, -1).join(", ")} or ${items[items.length - 1]}`;
}

/** Whose turn, as a trigger window names it. */
const TURN_OWNERS: Record<string, string> = { "your-turn": "your", "opponent-turn": "your opponent's" };

/** The actor of a trigger: "this unit", "an enemy unit", "a friendly EXORCIST unit", "this model". */
function actor(ref: unknown): string {
  if (ref == null || ref === "this-unit") return "this unit";
  if (ref === "this-model") return "this model";
  if (ref === "model-in-this-unit") return "a model in this unit";
  // A moment nested in an attack's: the unit making that attack.
  if (ref === "attacker") return "the attacking unit";
  if (ref === "selected-unit") return "the selected unit";
  // A moment nested in a triggered effect: the unit that triggered it.
  if (ref === "event-subject") return "the triggering unit";
  if (ref === "event-subject-model") return "the triggering model";
  if (typeof ref === "object") {
    const f = ref as P;
    // The unit an aura reaches, as the effect's aura names it (effect.ts withAuraRecipient).
    if (typeof f.aura_recipient === "string") return f.aura_recipient;
    if (typeof f.event_var === "string") return "that unit";
    if (f.selection_var != null || f.stratagem_target != null) return unitRefPhrase(f);
    if (Object.keys(f).some((key) => !["owner", "level", "state", "not_states", "all_of", "any_of", "none_of", "not_all_of", "any_of_filters"].includes(key))) return unitFilterPhrase(f);
    const owner = f.owner === "friendly" ? "friendly " : f.owner === "enemy" ? "enemy " : "";
    const noun = f.level === "model" ? "model" : "unit";
    const all = Array.isArray(f.all_of) ? `${(f.all_of as unknown[]).map(str).join(" ")} ` : "";
    const compact = keywordAlternatives(f);
    const anyMulti = !all && !compact && Array.isArray(f.any_of) && f.any_of.length > 1 ? `${orList((f.any_of as unknown[]).map(str))} ` : "";
    let s = withArticle(compact ? `${owner}${orList(compact)} ${noun}` : `${owner}${all}${anyMulti}${noun}`);
    if (Array.isArray(f.any_of_filters) && !compact) s += ` that is ${orList(alternativeFilters(f).map(unitFilterPhrase))}`;
    if (Array.isArray(f.any_of) && !anyMulti) s += ` with the ${orList((f.any_of as unknown[]).map(str))} keyword`;
    if (Array.isArray(f.none_of)) s += ` (excluding ${orList((f.none_of as unknown[]).map(str))} ${noun}s)`;
    if (Array.isArray(f.not_all_of)) s += ` (excluding ${(f.not_all_of as unknown[]).map(str).join(" ")} ${noun}s)`;
    const states = [
      ...(f.state != null ? [statePhrase(str(f.state))] : []),
      ...(Array.isArray(f.not_states) ? (f.not_states as unknown[]).map((x) => statePhrase(str(x), true)) : []),
    ];
    if (states.length) s += ` that is ${andList(states)}`;
    return s;
  }
  return dekebab(str(ref));
}

/** Kept as a no-op helper for clarity; keyword requirements are now folded directly into `actor()`. */
function actorKeywords(_ref: unknown): string {
  return "";
}

/** "a Transport within 6" of this model": the Transports a disembarked moment's filter allows. */
function transportPhrase(ref: unknown): string {
  const f = ref as P;
  const within = f !== null && typeof f === "object" && Object.keys(f).length === 1 ? f.within as P | undefined : undefined;
  return within != null ? `a Transport within ${rangePhrase(within.range)} of ${objectPhrase(within.of)}` : objectPhrase(ref);
}

/** An object phrase: "this unit", "an enemy unit". */
function objectPhrase(ref: unknown): string {
  if (ref == null || ref === "this-unit") return "this unit";
  if (ref === "this-model") return "this model";
  if (ref === "model-in-this-unit") return "a model in this unit";
  if (typeof ref === "object") return unitRefPhrase(ref);
  return dekebab(str(ref));
}

/** Whether a trigger's object is a unit filter (an object), not a role. */
function isFilterObject(ref: unknown): boolean {
  return typeof ref === "object" && ref !== null && !Array.isArray(ref);
}

/** The unit a used Stratagem targets: "this unit" for the holder's own role, else the object filter. */
function stratagemTarget(ref: unknown): string {
  return typeof ref === "object" && ref !== null && !Array.isArray(ref) ? objectPhrase(ref) : "this unit";
}

const ROLL_NOUN: Record<string, string> = {
  hit: "Hit roll", wound: "Wound roll", save: "saving throw", damage: "Damage roll", charge: "Charge roll",
  advance: "Advance roll", "battle-shock": "Battle-shock test", leadership: "Leadership test", hazard: "Hazard roll",
  psychic: "Psychic test", "desperate-escape": "Desperate Escape test", "dark-pact": "Dark Pact Leadership test",
  "blessings-of-khorne": "Blessings of Khorne roll", manoeuvre: "Agile Manoeuvre roll", channelling: "Channel the Warp roll",
  "deadly-demise": "Deadly Demise roll", attacks: "roll to determine the number of attacks",
};
const TEST_ROLLS = new Set(["battle-shock", "leadership", "desperate-escape"]);

const ATTACK_MODELS: Record<string, string> = { "this-model": "this model", "this-unit": "a model in this unit", "model-in-this-unit": "a model in this unit" };

/** An after-roll moment narrowed to unmodified faces: ", on an unmodified 6" (or 5+, or 2-3). */
function withUnmodified(t: AbilityTrigger, f: P, clause: string): string {
  const faces = f.unmodified as P | undefined;
  if (t.event !== "after-roll" || faces == null) return clause;
  const from = Number(faces.from);
  const to = Number(faces.to);
  return `${clause}, on an unmodified ${from === to ? `${from}` : to === 6 ? `${from}+` : `${from}-${to}`}`;
}

function rollClause(t: AbilityTrigger, f: P): string {
  // An ability's own dice ({of_ability}) read "Reanimation Protocols roll".
  const roll = typeof f.roll === "object" && f.roll != null ? "" : str(f.roll);
  const noun = ROLL_NOUN[roll] ?? `${rollWord(f.roll)} roll`;
  const subject = t.subject;
  const anyone = typeof subject === "object" && subject !== null && (subject as P).owner === "any" && Object.keys(subject).length === 1;
  if (t.event === "before-roll") {
    if (TEST_ROLLS.has(roll) && !anyone) return `when ${actor(subject)} takes a ${noun}`;
    const by = !anyone && ["hit", "wound", "damage"].includes(roll) ? ATTACK_MODELS[str(subject ?? "this-unit")] ?? (typeof subject === "object" ? `a model in ${actor(subject)}` : undefined) : undefined;
    return `before ${/^[aeiou]/i.test(noun) ? "an" : "a"} ${noun} is made${by ? ` for an attack made by ${by}` : ""}`;
  }
  if (f.result === "success" && roll === "hit") {
    // A bound unit's hits: "each time an attack made by that unit scores a hit".
    if (typeof subject === "object" && subject !== null && typeof (subject as P).event_var === "string") return "each time an attack made by that unit scores a hit";
    return "after scoring a hit";
  }
  if (f.result === "success" && roll === "wound") {
    const by = anyone ? "" : ` made by ${ATTACK_MODELS[str(subject ?? "this-unit")] ?? `a model in ${actor(subject)}`}`;
    return `each time an attack${by} scores a wound`;
  }
  if (f.result === "success" && roll === "dark-pact") return "each time the unit makes a Dark Pact and passes its Leadership test";
  // Whose roll it was and how it came out: "when the unit fails a Battle-shock test", "after a saving throw made for this model is failed".
  const article = /^[aeiou]/i.test(noun) ? "an" : "a";
  const named = subject != null && !anyone;
  if (f.result === "failure" || f.result === "success") {
    const passed = f.result === "success";
    if (TEST_ROLLS.has(roll)) return `when ${actor(subject)} ${passed ? "passes" : "fails"} ${article} ${noun}`;
    if (passed) return `after a successful ${noun}${named ? ` made for ${actor(subject)}` : ""}`;
    return `after ${article} ${noun}${named ? ` made for ${actor(subject)}` : ""} is failed`;
  }
  if (named) return TEST_ROLLS.has(roll) ? `after ${actor(subject)} takes ${article} ${noun}` : `after ${actor(subject)} makes ${article} ${noun}`;
  if (roll === "psychic") return "after a Psychic test is taken";
  if (roll === "blessings-of-khorne") return "each time you make a Blessings of Khorne roll";
  return `after ${/^[aeiou]/i.test(noun) ? "an" : "a"} ${noun} is made`;
}

const USED: Record<string, string> = {
  "dark-pact": "makes a Dark Pact", "act-of-faith": "performs an Act of Faith", manoeuvre: "performs an Agile Manoeuvre",
  ritual: "attempts a Ritual", order: "issues an Order", doctrine: "selects a Combat Doctrine", contract: "invokes its contract",
};

/** The event family's own clause, before proximity, condition and options. */
function eventPhrase(t: AbilityTrigger): string {
  const f = (t.filter ?? {}) as P;
  const who = actor(t.subject);
  switch (t.event) {
    case "army-selected":
      return "when selecting your army";
    case "battle-started":
      return "at the start of the battle";
    case "battle-formations-declared":
      return "when declaring Battle Formations";
    case "deployment-ended":
      return "after deployment";
    case "round-started":
      return "at the start of the battle round";
    case "round-ended":
      return "at the end of the battle round";
    case "turn-started":
      return "at the start of each turn";
    case "turn-ended":
      return "at the end of the turn";
    case "step-started":
      return `at the start of the ${titleCase(str(f.step))} step`;
    case "selected": {
      if (f.to == null) return `when ${who} is selected`;
      if (f.to === "observe") return `each time ${who} is selected as an Observer unit`;
      if (f.to === "move" && Array.isArray(f.move_types)) {
        // "selected to make a Normal move", "selected to make an Advance or Fall Back move".
        const kinds = moveKinds(f.move_types);
        const move = `${kinds ? `${/^[aeiou]/i.test(kinds) ? "an" : "a"} ${kinds}` : "a"} move`;
        return `when ${who} is selected to make ${move}${selectedMode(f)}`;
      }
      return `when ${who} is selected to ${f.to === "attack" ? "shoot or fight" : dekebab(str(f.to))}`;
    }
    case "targets-selected": {
      if (f.kind === "stratagem") return `when ${t.object == null || t.object === "this-unit" || t.object === "this-model" ? "this model's unit" : objectPhrase(t.object)} is targeted with a Stratagem`;
      if (f.kind === "ability" && t.source_ability) {
        const s = t.source_ability;
        return `when ${actor(t.subject)} is selected by the ${titleCase(s.ability_id)} ability of a ${s.owner} ${(s.keywords ?? []).join(" ")} unit`.replace(/\s+unit$/, " unit");
      }
      if (f.kind === "charge") {
        if (t.object != null) return `when ${who} selects ${objectPhrase(t.object)} as a charge target`;
        return typeof t.subject === "object" ? `after ${who} selects targets for its charge but before it makes a Charge move` : "when a Charge is declared";
      }
      if (t.object != null) return `when ${who} targets ${objectPhrase(t.object)}${f.all_attacks === true ? " with all of its attacks" : ""}`;
      return `when ${who} selects its targets`;
    }
    case "move-started": {
      // "at the start of this unit's move", "just before it Consolidates": the move is about to be made.
      const kinds = Array.isArray(f.move_types) ? moveKinds(f.move_types) : "";
      const move = `${kinds ? `${/^[aeiou]/i.test(kinds) ? "an" : "a"} ${kinds}` : "a"} move`;
      return typeof t.subject === "object" ? `each time ${who} starts ${move}` : `when ${who} starts ${move}`;
    }
    case "move-ended": {
      if (f.through === "tall-terrain") return `when ${who} moves through terrain over 4" tall`;
      if (f.through === "terrain") return `when ${who} moves through terrain`;
      const kinds = Array.isArray(f.move_types) ? moveKinds(f.move_types) : "";
      const enemy = typeof t.subject === "object";
      // Another unit's move is a reaction window: "each time an enemy unit ends a move".
      if (enemy && kinds === "Fall Back" && t.object == null) return `each time ${who} Falls Back`;
      const tail = t.object != null ? ` from ${objectPhrase(t.object)}` : "";
      const move = `${kinds ? `${/^[aeiou]/i.test(kinds) ? "an" : "a"} ${kinds}` : "a"} move${tail}`;
      return enemy ? `each time ${who} ends ${move}` : `when ${who} ends ${move}`;
    }
    case "set-up": {
      const from: Record<string, string> = {
        "deep-strike": "is set up by Deep Strike", "strategic-reserves": "arrives from Strategic Reserves",
        "cult-ambush": "is set up using Cult Ambush", transport: "is set up from a Transport",
      };
      return `when ${who} ${from[str(f.from)] ?? "is set up"}`;
    }
    case "disembarked": {
      const from = f.transport == null ? "a Transport" : f.transport === "this-unit" || f.transport === "this-model" ? "this Transport" : transportPhrase(f.transport);
      return `when ${who} disembarks from ${from}${f.timing === "after-set-up" ? ", after it has been set up" : ""}`;
    }
    case "before-roll":
    case "after-roll":
      return withUnmodified(t, f, rollClause(t, f));
    case "damage-allocated": {
      const type = allocatedAttackType(t);
      const allocated = type ? `when a ${type} attack is allocated` : "when damage is allocated";
      return t.object != null && t.object !== "this-unit" ? `${allocated} to ${objectPhrase(t.object)}` : allocated;
    }
    case "attacks-resolved":
      // A bound unit's attacks of either kind: "after that unit has finished making its attacks".
      if (typeof t.subject === "object" && t.object == null && f.kind == null && typeof (t.subject as P).event_var === "string") return `after ${who} has finished making its attacks`;
      if (typeof t.subject === "object") return t.object != null ? `after ${who} has shot and targeted ${objectPhrase(t.object)}` : `after ${who} ${f.kind === "fight" ? "fights" : f.kind === "attack" ? "resolves its attacks" : "shoots"}`;
      return f.kind === "fight" ? `after ${who} resolves its attacks in a fight` : `after ${who} resolves its attacks`;
    case "destroyed": {
      const obj = t.object;
      const melee = f.attack_type === "melee" ? " in melee" : "";
      // A subject names who destroyed the object: "each time the unit destroys an enemy unit".
      if (t.subject != null) return `each time ${who} destroys ${obj == null ? "a unit" : objectPhrase(obj)}${melee}`;
      if (obj == null || obj === "this-unit") return `when this unit is destroyed${melee}`;
      if (typeof obj === "object" && (obj as P).designated != null && Object.keys(obj as P).length === 1) return "each time your quarry is destroyed";
      return `${melee ? "when" : "each time"} ${objectPhrase(obj)} is destroyed${melee}`;
    }
    case "model-destroyed": {
      if (f.timing === "before-removal") return "before this model is removed from play";
      // Resolved once the units embarked within the destroyed model have disembarked.
      if (f.timing === "after-emergency-disembark") {
        const { timing: _timing, ...rest } = f;
        return `${eventPhrase({ ...t, filter: rest } as AbilityTrigger)}, after the units embarked within it have made their emergency disembark moves`;
      }
      if (f.first === true) return "the first time a model in this unit is destroyed";
      const obj = t.object;
      // "When the last Guardian Defender model in this unit is destroyed".
      if (f.last === true) return `when the last ${lastModelPhrase(obj)} is destroyed`;
      // A subject names who destroyed the model: "each time this unit destroys an enemy CHARACTER model".
      if (t.subject != null) {
        if (obj === "this-model") return `when this model is destroyed by ${who}`;
        if (obj === "model-in-this-unit" || obj === "this-unit" || obj == null) return `when a model in this unit is destroyed by ${who}`;
        return `each time ${who} destroys ${objectPhrase(obj)}`;
      }
      if (obj === "this-model") return "when this model is destroyed";
      // A model of this unit dying: the object names the model's unit, never the whole unit's destruction.
      if (obj === "model-in-this-unit" || obj === "this-unit" || obj == null) return "when a model in this unit is destroyed";
      return `when ${objectPhrase(obj)} is destroyed`;
    }
    case "used": {
      // A rule your opponent used: the subject names only the enemy owner.
      const subj = t.subject as P | undefined;
      const opponent = typeof subj === "object" && subj !== null && subj.owner === "enemy" && Object.keys(subj).length === 1;
      const which = usedAbilityPhrase(f);
      if (which != null) return `each time ${opponent ? "your opponent" : who} uses ${which}`;
      // One named rule: who used it, else you (the holder) for an ability or Stratagem.
      const named = namedUsePhrase(f);
      if (named != null) {
        const verb = f.kind === "manoeuvre" ? "performs" : "uses";
        if (f.kind === "stratagem" && t.object != null) return opponent ? `each time your opponent targets ${stratagemTarget(t.object)} with ${named}` : `when you target ${stratagemTarget(t.object)} with ${named}`;
        if (opponent) return `each time your opponent ${verb} ${named}`;
        if (t.subject == null && (f.kind === "ability" || f.kind === "stratagem")) return `when you use ${named}`;
        return `each time ${who} ${verb} ${named}`;
      }
      // "When its unit is targeted with a Stratagem": the object is the unit the Stratagem is aimed at.
      if (f.kind === "stratagem" && t.object != null) return opponent ? `each time your opponent targets ${stratagemTarget(t.object)} with a Stratagem` : `each time you target ${stratagemTarget(t.object)} with a Stratagem`;
      if (f.kind === "stratagem") return opponent ? "each time your opponent uses a Stratagem" : "each time you use a Stratagem";
      if (opponent && f.kind === "ability" && f.id == null) return "each time your opponent uses an ability";
      if (f.kind === "ritual" && f.result === "success") return `each time ${who} manifests a Ritual`;
      if (f.kind === "act-of-faith") return f.result === "success" ? "after an Act of Faith is completed" : "when an Act of Faith is performed";
      // "after the bearer issues an Order to a SQUADRON unit": who issued it, and the unit it went to.
      if (f.kind === "order" && isFilterObject(t.object)) return `each time ${who} issues an Order to ${objectPhrase(t.object)}`;
      if (f.kind === "order" && t.object != null) return "each time an Order is issued to the unit";
      if (f.kind === "contract" && f.result === "success") return "each time you complete a Contract";
      return `each time ${who} ${USED[str(f.kind)] ?? `uses ${dekebab(str(f.kind))}`}`;
    }
    case "state-changed":
      // "Caused an enemy unit that was not Below Half-strength to become Below Half-strength".
      if (f.by != null && f.strength != null) return `when ${f.by === "this-unit" ? "this unit" : unitRefPhrase(f.by)} causes ${who} to ${f.strength === "below-half" ? "become Below Half-strength" : "fall below its Starting Strength"}`;
      if (f.strength === "below-half") return `when ${who} becomes Below Half-strength`;
      if (f.strength === "below-starting") return `when ${who} falls below its Starting Strength`;
      return `when ${who} becomes ${capWord(str(f.state))}`;
    case "designation-changed":
      return f.tag === "EMPOWERED" ? `each time ${who} is Empowered` : `each time ${who} becomes ${str(f.tag)}`;
    case "designation-resolved":
      return f.tag === "OATH OF MOMENT TARGET" ? "when you fulfil an Oath" : `when a ${str(f.tag)} designation is resolved`;
    case "marker-removed":
      return `each time one of your ${titleCase(str(f.marker))} markers is removed`;
    case "objective-gained":
      return "when you gain control of an objective";
    case "resource-gained":
      if (f.pool === "miracle-dice") return "when a Miracle die is generated";
      if (f.pool === "cp" || f.pool === "command-point") return `each time ${typeof t.subject === "object" && (t.subject as P).owner === "enemy" ? "your opponent gains" : "you gain"} a CP${f.via === "ability" ? " as the result of an ability" : ""}`;
      return `each time ${dekebab(str(f.pool))} is gained`;
    case "resource-spent":
      if (f.pool === "flux") return "each time a Flux token is spent";
      if (f.pool === "yield-points") return "each time you spend Yield points";
      // "When you spend 1 Pain token to Empower that friendly unit": the unit the spend Empowers.
      if (f.tag === "empowered") return `each time you spend ${resourceNoun(f.pool, undefined)} to Empower ${t.object != null ? objectPhrase(t.object) : "a unit"}`;
      return `each time ${dekebab(str(f.pool))} is spent`;
    default:
      return `when ${dekebab(str(t.event))}`;
  }
}

/**
 * The attack type a damage-allocated trigger's whole condition names ("each time a ranged attack is
 * allocated"), which the moment's own clause then says; undefined for any other condition.
 */
function allocatedAttackType(t: AbilityTrigger): string | undefined {
  const c = t.condition;
  if (t.event !== "damage-allocated" || !c || c.operator || c.type !== "attack-is") return undefined;
  const params = c.parameters ?? {};
  const type = params.attack_type;
  return Object.keys(params).length === 1 && (type === "ranged" || type === "melee" || type === "psychic") ? type : undefined;
}

/** "At the start of your turn": a turn boundary narrowed only by whose turn. */
function turnBoundary(t: AbilityTrigger): string | null {
  if (t.event !== "turn-started" && t.event !== "turn-ended") return null;
  const c = t.condition;
  if (!c || c.type !== "player-turn-is") return null;
  const owner = TURN_OWNERS[str(c.parameters?.turn)];
  return owner ? `at the ${t.event === "turn-started" ? "start" : "end"} of ${owner} turn` : null;
}

/** "At the start of your Command phase": a phase boundary narrowed only by phase and whose turn. */
function phaseBoundary(t: AbilityTrigger): string | null {
  if (t.event !== "phase-started" && t.event !== "phase-ended") return null;
  const operands = !t.condition ? [] : t.condition.operator === "and" ? t.condition.operands ?? [] : [t.condition];
  if (operands.some((c) => c.operator || (c.type !== "phase-is" && c.type !== "player-turn-is") || c.parameters?.step != null)) return null;
  const phase = operands.find((c) => c.type === "phase-is")?.parameters?.phase;
  const turn = operands.find((c) => c.type === "player-turn-is")?.parameters?.turn;
  if (typeof phase !== "string" || operands.length !== (turn === undefined ? 1 : 2)) return null;
  if (turn !== undefined && !(String(turn) in TURN_OWNERS)) return null;
  const owner = turn === undefined ? "the" : TURN_OWNERS[String(turn)]!;
  return `at the ${t.event === "phase-started" ? "start" : "end"} of ${owner} ${capWord(phase)} phase`;
}

/**
 * A trigger condition's phase and whose turn, as a phrase on the moment ("during your Shooting
 * phase", "in your opponent's turn"), and whatever else the condition says. Only a plain phase-is
 * and player-turn-is (at most one each, joined by "and") make a window.
 */
export function phaseWindow(condition: Condition): { window: string; rest: Condition | null; phase?: string; owner?: string } {
  const operands = condition.operator === "and" ? condition.operands ?? [] : condition.operator ? [] : [condition];
  const phases = operands.filter((c) => c.type === "phase-is");
  const turns = operands.filter((c) => c.type === "player-turn-is");
  const owner = TURN_OWNERS[str(turns[0]?.parameters?.turn)];
  const phase = phases[0]?.parameters?.phase;
  if (phases.length > 1 || turns.length > 1 || (turns.length === 1 && !owner) || (phases.length === 1 && typeof phase !== "string") || phases.length + turns.length === 0) {
    return { window: "", rest: condition };
  }
  // A step narrows the phase ("during the Reinforcements step of your opponent's Movement phase"); it is no phase boundary.
  const step = phases[0]?.parameters?.step != null;
  const window = step ? stepWindow(phases[0]!.parameters as P, owner ?? "the")
    : phases.length ? `during ${owner ?? "the"} ${capWord(phase as string)} phase` : `in ${owner} turn`;
  const others = operands.filter((c) => !phases.includes(c) && !turns.includes(c));
  return {
    window, rest: others.length === 0 ? null : others.length === 1 ? others[0]! : { operator: "and", operands: others },
    ...(phases.length && !step ? { phase: phase as string } : {}), ...(owner ? { owner } : {}),
  };
}

/** `phase-ended` with "disembarked this turn and battle-shocked": the one boundary that reads as an if. */
function disembarkBattleShock(c: Condition | undefined): boolean {
  if (c?.operator !== "and" || c.operands?.length !== 2) return false;
  const [first, second] = c.operands;
  return first?.type === "happened" && first.parameters?.event === "disembarked" && second?.type === "matches" && (second.parameters?.filter as P | undefined)?.state === "battle-shocked" && Object.keys(second.parameters?.filter as P).length === 1;
}

/**
 * The attacks a destruction's filter names: "with a quake cannon attack", "with a [PSYCHIC] weapon".
 * A destroyed unit's melee already reads "in melee" in eventPhrase, so a unit's attack type adds
 * nothing here; a model's does ("in melee", "with a ranged attack").
 */
function destroyAttackPhrase(t: AbilityTrigger, f: P): string {
  if (t.event !== "destroyed" && t.event !== "model-destroyed") return "";
  if (f.weapons != null) {
    const weapons = f.weapons as P;
    if (Object.keys(weapons).length === 1 && weapons.name != null) return ` with a ${str(weapons.name)} attack`;
    if (Object.keys(weapons).length === 1 && weapons.keyword != null && !Array.isArray(weapons.keyword)) return ` with a ${bracketKeyword(weapons.keyword)} weapon`;
    return ` with ${weaponNoun({ weapons })}`;
  }
  if (t.event === "model-destroyed" && f.attack_type) return f.attack_type === "melee" ? " in melee" : ` with a ${str(f.attack_type)} attack`;
  return "";
}

/** "At the start of the first battle round": a round boundary narrowed to one battle round. */
function roundBoundary(t: AbilityTrigger): string | null {
  if (t.event !== "round-started" && t.event !== "round-ended") return null;
  const c = t.condition;
  if (!c || c.operator || c.type !== "battle-round") return null;
  const p = (c.parameters ?? {}) as P;
  if (p.min != null && p.max != null && Number(p.min) === Number(p.max)) {
    return `at the ${t.event === "round-started" ? "start" : "end"} of the ${ord(Number(p.min))} battle round`;
  }
  return null;
}

/** The model a last-model destruction names: "GUARDIAN DEFENDER model in this unit". */
function lastModelPhrase(obj: unknown): string {
  const o = (typeof obj === "object" && obj !== null ? obj : {}) as P;
  const keywords = Array.isArray(o.all_of) ? (o.all_of as string[]).join(" ") : Array.isArray(o.any_of) ? orList(o.any_of as string[]) : "";
  const model = `${keywords ? `${keywords} ` : ""}model`;
  return o.member_of === "this-unit" ? `${model} in this unit` : `${model} in ${objectPhrase(obj)}`;
}
/** Reactive trigger → front-of-sentence lead clause ("an enemy unit ends a move within 9\" of this model"). */
export function describeTrigger(t: AbilityTrigger): string {
  const clock = t.event === "phase-started" || t.event === "phase-ended";
  const plain = !t.proximity && !t.binds_die_variable && !t.binds_selected_die_variable && (t.subject == null || t.subject === "this-unit");
  const boundary = plain ? phaseBoundary(t) ?? turnBoundary(t) ?? roundBoundary(t) : null;
  if (boundary) return t.optional ? `${boundary}, you can use this ability` : boundary;
  const edge = t.event === "phase-started" ? "start" : t.event === "phase-ended" ? "end" : null;
  const disembarkShock = t.event === "phase-ended" && disembarkBattleShock(t.condition);
  const split = t.condition && !disembarkShock && allocatedAttackType(t) === undefined ? phaseWindow(t.condition) : null;
  let s = !clock ? eventPhrase(t)
    : split?.phase ? `at the ${edge} of ${split.owner ?? "the"} ${capWord(split.phase)} phase`
      : `at the ${edge} of each phase`;
  s += actorKeywords(t.subject);
  const f = (t.filter ?? {}) as P;
  s += destroyAttackPhrase(t, f);
  if (f.weapons != null && t.event !== "destroyed" && t.event !== "model-destroyed" && f.by == null) s += ` with ${weaponNoun({ weapons: f.weapons })}`;
  if (f.by != null && !(t.event === "state-changed" && f.strength != null)) {
    const source = f.by === "this-unit" ? "this unit" : unitRefPhrase(f.by);
    const type = f.attack_type && t.event !== "destroyed" ? `${str(f.attack_type)} ` : "";
    const weapon = f.weapons != null ? ` with ${weaponNoun({ weapons: f.weapons })}` : "";
    s += type || weapon ? ` by ${type}attacks made by ${source}${weapon}` : ` by ${source}`;
  }
  s += eventRelationPhrase(f);
  if (f.phase != null) s += ` in the ${capWord(str(f.phase))} phase`;
  // A destruction resolved once its attacker is done: "…, after the attacking unit has resolved its attacks".
  if (f.timing === "after-attacks") s += ", after the attacking unit has resolved its attacks";
  // "Just after … is destroyed, before making its Deadly Demise roll".
  if (f.timing === "before-deadly-demise") s += ", before its Deadly Demise roll is made";
  // "Ends a move within 8 inches of your markers, before removing those markers".
  if (f.timing === "before-marker-removal") s += ", before those markers are removed";
  if (t.proximity?.range != null) {
    const of = t.proximity.of == null || t.proximity.of === "this-unit" ? "this unit" : placeRefPhrase(t.proximity.of);
    s += ` within ${rangePhrase(t.proximity.range)} of ${of}`;
  }
  if (disembarkShock) s += ", if this unit disembarked from a Transport this turn and is Battle-shocked";
  else if (split) {
    if (edge && !split.phase && split.owner) s += ` in ${split.owner} turn`;
    else if (!edge && split.window) s += ` ${split.window}`;
    if (split.rest) s += `, if ${describeCondition(split.rest)}`;
  }
  if (t.optional) s += ", you can use this ability";
  return s;
}

/** " using the Tactical Disembarkation rules": the named mode of the move a unit is selected to make. */
function selectedMode(f: Record<string, unknown>): string {
  if (f.mode == null) return "";
  const mode = titleCase(str(f.mode));
  return ` using the ${(f.move_types as unknown[]).includes("disembark") ? `${mode} Disembarkation` : mode} rules`;
}
